from Crypto.Util.number import getPrime, bytes_to_long
import random

flag = b"holic{fake_flag_for_testingggggggggggggggggggggg}"
m = bytes_to_long(flag)

e = 5
p = getPrime(512)
q = getPrime(512)
n = p * q
assert m < n

pad = random.getrandbits(32)
m2 = m + pad
assert m2 < n

c1 = pow(m, e, n)
c2 = pow(m2, e, n)

print(f"n = {n}")
print(f"e = {e}")
print(f"c1 = {c1}")
print(f"c2 = {c2}")


